/* ==========================================================================
   1. THEME DESIGN TOKENS & CSS VARIABLES (6 BIOMORPHIC THEMES)
   ========================================================================== */
:root {
  /* Shared Spacing & Physics */
  --font-main: 'Plus Jakarta Sans', 'Outfit', -apple-system, sans-serif;
  --ease-fluid: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-smooth: cubic-bezier(0.4, 0.0, 0.2, 1);
  --radius-blob-1: 32px 48px 36px 52px / 48px 36px 56px 32px;
  --radius-blob-2: 54px 30px 48px 36px / 32px 52px 36px 48px;
  --radius-blob-3: 40px 60px 45px 55px / 55px 42px 58px 40px;
  --radius-card: 28px 36px 32px 40px / 36px 28px 44px 32px;
  --radius-pill: 999px;
  --transition-theme: background-color 0.6s var(--ease-smooth), color 0.6s var(--ease-smooth), border-color 0.6s var(--ease-smooth), box-shadow 0.6s var(--ease-smooth);
}

