/* ==========================================================================
   2. GLOBAL RESET & BASE STYLES
   ========================================================================== */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: var(--font-main);
  -webkit-font-smoothing: antialiased;
}

body {
  background: var(--bg-color);
  background-image: var(--bg-gradient);
  background-attachment: fixed;
  color: var(--text-main);
  min-height: 100vh;
  overflow-x: hidden;
  transition: var(--transition-theme);
  position: relative;
}

/* Custom Organic Scrollbar */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.03);
}
::-webkit-scrollbar-thumb {
  background: var(--accent-1);
  border-radius: var(--radius-pill);
  border: 3px solid transparent;
  background-clip: padding-box;
}

/* ==========================================================================
   3. BACKGROUND MORPHING LIVING BLOBS (BIOMORPHIC AESTHETICS)
   ========================================================================== */
.bio-canvas-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.living-blob {
  position: absolute;
  filter: blur(50px);
  opacity: 0.85;
  mix-blend-mode: multiply;
  transition: var(--transition-theme);
  will-change: transform, border-radius;
}

[data-theme="biolum"] .living-blob,
[data-theme="forest"] .living-blob,
[data-theme="cyberbio"] .living-blob {
  mix-blend-mode: screen;
  opacity: 0.65;
}

.blob-1 {
  width: 520px;
  height: 520px;
  top: -100px;
  left: -100px;
